#!/usr/bin/env node
/**
 * Tiny translation pipeline.
 *
 * shared/i18n/<language>.json is the single source of truth. This script
 * validates key and placeholder parity, then generates the Android string
 * resources and the web dictionary. Run with --check in CI to fail when a
 * generated file is stale or a language is incomplete.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const languages = ['en', 'ha', 'yo', 'ig'];
const sourceDir = join(root, 'shared', 'i18n');
const checkOnly = process.argv.includes('--check');
const errors = [];

function readJson(language) {
  const path = join(sourceDir, `${language}.json`);
  if (!existsSync(path)) {
    errors.push(`Missing translation source: ${path}`);
    return {};
  }
  const raw = readFileSync(path, 'utf8');
  try {
    return JSON.parse(raw);
  } catch (error) {
    errors.push(`${language}.json is not valid JSON: ${error.message}`);
    return {};
  }
}

const dictionaries = Object.fromEntries(languages.map((language) => [language, readJson(language)]));
const englishKeys = Object.keys(dictionaries.en);

if (englishKeys.length === 0) {
  errors.push('English translation source is empty.');
}

function placeholderNames(value) {
  return [...value.matchAll(/\{([a-zA-Z0-9_]+)(?::([a-zA-Z]))?\}/g)]
    .map((match) => `${match[1]}:${match[2] ?? 's'}`)
    .sort();
}

function pluralBase(key) {
  return key.endsWith('_one') ? key.slice(0, -4) : key.endsWith('_other') ? key.slice(0, -6) : null;
}

const pluralBases = new Set();
for (const key of englishKeys) {
  const base = pluralBase(key);
  if (!base) continue;
  pluralBases.add(base);
  for (const language of languages) {
    const dictionary = dictionaries[language];
    if (!Object.prototype.hasOwnProperty.call(dictionary, `${base}_one`)) {
      errors.push(`${language}.json is missing ${base}_one`);
    }
    if (!Object.prototype.hasOwnProperty.call(dictionary, `${base}_other`)) {
      errors.push(`${language}.json is missing ${base}_other`);
    }
  }
}
for (const base of pluralBases) {
  for (const language of languages) {
    for (const suffix of ['_one', '_other']) {
      if (!englishKeys.includes(base + suffix)) errors.push(`English plural pair is incomplete: ${base}`);
    }
  }
}

for (const language of languages) {
  const dictionary = dictionaries[language];
  const keys = Object.keys(dictionary);
  for (const key of englishKeys) {
    if (!Object.prototype.hasOwnProperty.call(dictionary, key)) errors.push(`${language}.json is missing key: ${key}`);
  }
  for (const key of keys) {
    if (!englishKeys.includes(key)) errors.push(`${language}.json has an unknown key: ${key}`);
    if (typeof dictionary[key] !== 'string' || dictionary[key].trim() === '') {
      errors.push(`${language}.json has an empty value for: ${key}`);
    }
  }
  for (const key of englishKeys) {
    if (typeof dictionary[key] !== 'string' || typeof dictionaries.en[key] !== 'string') continue;
    const expected = placeholderNames(dictionaries.en[key]).join(',');
    const actual = placeholderNames(dictionary[key]).join(',');
    if (expected !== actual) {
      errors.push(`${language}.json placeholder mismatch for ${key}: expected [${expected}] got [${actual}]`);
    }
  }
}

function xmlEscape(value) {
  let text = value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '\\"')
    .replaceAll("'", "\\'");
  if (text.startsWith('@') || text.startsWith('?')) text = `\\${text}`;
  return text;
}

function androidValue(value) {
  const order = [];
  const sentinels = new Map();
  let converted = value.replace(/\{([a-zA-Z0-9_]+)(?::([a-zA-Z]))?\}/g, (_match, name, type) => {
    const kind = type ?? 's';
    let index = order.findIndex((entry) => entry.name === name && entry.kind === kind);
    if (index < 0) {
      order.push({ name, kind });
      index = order.length - 1;
    }
    const token = `__TINY_PH_${index}_${kind}__`;
    sentinels.set(token, `%${index + 1}$${kind}`);
    return token;
  });
  converted = xmlEscape(converted);
  // Android's formatter treats stray percent signs as format specifiers.
  converted = converted.replaceAll('%', '%%');
  for (const [token, replacement] of sentinels) converted = converted.replaceAll(token, replacement);
  return converted;
}

function androidName(key) {
  if (!/^[a-z][a-z0-9_]*$/.test(key)) throw new Error(`Invalid Android resource name: ${key}`);
  return key;
}

function androidXml(language) {
  const dictionary = dictionaries[language];
  const lines = [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<!-- GENERATED by tools/generate-i18n.mjs from shared/i18n/' + language + '.json. Do not edit by hand. -->',
    '<resources>',
  ];
  const emitted = new Set();
  for (const key of englishKeys) {
    if (emitted.has(key)) continue;
    const base = pluralBase(key);
    if (base) {
      if (emitted.has(base)) continue;
      emitted.add(`${base}_one`);
      emitted.add(`${base}_other`);
      lines.push(`    <plurals name="${androidName(base)}">`);
      lines.push(`        <item quantity="one">${androidValue(dictionary[`${base}_one`])}</item>`);
      lines.push(`        <item quantity="other">${androidValue(dictionary[`${base}_other`])}</item>`);
      lines.push('    </plurals>');
      continue;
    }
    lines.push(`    <string name="${androidName(key)}">${androidValue(dictionary[key])}</string>`);
  }
  lines.push('</resources>', '');
  return lines.join('\n');
}

function webDictionary() {
  const serialised = JSON.stringify(dictionaries, null, 2);
  return `// GENERATED by tools/generate-i18n.mjs from shared/i18n/*.json. Do not edit by hand.\n` +
    `export const dictionaries = ${serialised} as const;\n\n` +
    'export type Language = keyof typeof dictionaries;\n' +
    'export type TranslationKey = keyof typeof dictionaries.en;\n' +
    'export const supportedLanguages: Language[] = ["en", "ha", "yo", "ig"];\n';
}

if (errors.length > 0) {
  console.error('Translation validation failed:');
  for (const error of [...new Set(errors)]) console.error(`  - ${error}`);
  process.exit(1);
}

const outputs = new Map();
for (const language of languages) {
  const dir = language === 'en'
    ? join(root, 'app', 'src', 'main', 'res', 'values')
    : join(root, 'app', 'src', 'main', 'res', `values-${language}`);
  outputs.set(join(dir, 'strings.xml'), androidXml(language));
}
outputs.set(join(root, 'web', 'src', 'i18n', 'dictionaries.ts'), webDictionary());

let stale = false;
for (const [path, content] of outputs) {
  if (checkOnly) {
    const current = existsSync(path) ? readFileSync(path, 'utf8') : '';
    if (current.replaceAll('\r\n', '\n') !== content) {
      stale = true;
      console.error(`Stale generated file: ${path}`);
    }
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content, 'utf8');
    console.log(`Generated ${path}`);
  }
}

if (checkOnly && stale) {
  console.error('Run: node tools/generate-i18n.mjs');
  process.exit(1);
}
if (checkOnly) console.log(`Translations valid: ${englishKeys.length} keys across ${languages.length} languages.`);
